css:
.stage {
  position: relative;
  min-height: 240px;
  padding: 16px;
  border: 2px dashed #a1a1aa;
}

.page {
  margin: 0;
}

.toast {
  position: absolute;
  inset: auto 16px 16px auto; /* right and bottom only */
  z-index: 1;
  padding: 10px 16px;
  border-radius: 6px;
  background: #18181b;
  color: #fafafa;
}
